details.codeblock:
#[async_trait::async_trait]
pub trait RepoEnginePort: Send + Sync {
    /// 有界筛选读取（对齐 loro-repo#330 where/omit 与已筛选标记校验）
    async fn query_entries(&self, room: &RoomId, query: BoundedRoomQuery) -> Result<FilteredSnapshot, RepoError>;
    /// 增量订阅（仅推送变更路径/JSON-Patch，禁止全表重扫）
    async fn subscribe_room(&self, room: &RoomId, scope: ReadScope) -> Result<BoxStream<'static, RoomDelta>, RepoError>;
    /// 携带明确本地作者身份提交变更并进入引擎 Outbox（防止 #328 已提交基线误判）
    async fn commit_authored(&self, room: &RoomId, author: WriterId, ops: RoomMutation) -> Result<CommitVersion, RepoError>;
    /// 配置远端同步传输（对齐 loro-repo#341: WebSocket -> SSE -> LongPoll）与 Token 刷新源
    async fn configure_cloud_sync(&self, ws: &WorkspaceId, transport: LiveTransportPolicy, tokens: Arc<dyn StreamsTokenSource>) -> Result<(), RepoError>;
    /// 注入 E2EE 密钥与缺钥回补钩子（引擎不存主密钥，遇未知 epoch/writer 回调 catch-up）
    async fn install_e2ee_keys(&self, ws: &WorkspaceId, bundle: VerifiedEpochKeys, on_missing: Arc<dyn MissingKeyHandler>) -> Result<(), RepoError>;
}

/// 在纯无头 Linux 服务器（无 Electron 共驻）与桌面共驻场景下的引擎连接策略
pub enum RepoEngineAttachment {
    /// 连接本机已运行的共享 loro-repo-engine 守护进程（按 build 序号校验能力与平滑接管）
    ConnectSharedDaemon { socket_path: PathBuf, min_build: u64 },
    /// 纯 CLI / 服务器独立运行时按需拉起受管 loro-repo-engine 宿主（或在未来直接内嵌 crate）
    ManagedSidecarEngine { binary_path: PathBuf, data_dir: PathBuf },
}

/// 运行时加载的后端连接画像（彻底取代编译期写死的 LODY_AUTH_URL / LODY_SERVER_URL）
pub enum DeploymentTopology {
    /// 纯本地开源/单机模式：零网络请求，所有远端 Port 为 None
    LocalOnly,
    /// 官方公有云或企业私有化自托管实例（通过 --server 发现或 profile.toml 注入）
    Connected(BackendProfile),
}

pub struct BackendProfile {
    pub profile_id: ProfileNamespaceId,       // 由规范化 origin tuple 派生，隔离本地存储目录
    pub discovery_issuer: Url,                // 例: https://lody.corp.internal
    pub control_rpc_url: Url,                 // Convex Cloud 或自托管 convex-local-backend
    pub auth_site_url: Url,                   // OIDC / Better-Auth HTTP 站点（显式下发，禁止域名字符串替换推导）
    pub blob_gateway_url: Option<Url>,        // CF Worker 或自托管 Node+OpenDAL 网关
    pub runtime_artifacts: ArtifactSourceConfig, // PublicCdn | MirrorUrl(Url) | AirGappedLocalDir(PathBuf)
    pub iroh_relays: Option<IrohRelayConfig>, // 官方或企业自建私有 Iroh Relay 节点列表
    pub tls_policy: TlsTrustPolicy,           // SystemRoots | WithCustomCaPem(PathBuf)
    pub capabilities: CapabilitySet,          // 动态门控 remotePreview / githubIntegration / sso 等
}

/// 兼容 Cloudflare R2 与自托管 OpenDAL (S3 / MinIO / OSS / LocalFS) 的协商式上传抽象
pub enum NegotiatedUploadPlan {
    SingleStreamPut { target_url: Url, headers: HeaderMap },
    PresignedMultipart { upload_id: String, part_size: usize, part_urls: Vec<Url>, complete_url: Url },
    GatewayStagedChunks { session_url: Url, chunk_bytes: usize },
}

#[async_trait::async_trait]
pub trait BlobTransferPort: Send + Sync {
    async fn negotiate_upload(&self, req: UploadIntent) -> Result<NegotiatedUploadPlan, BlobError>;
    async fn execute_upload(&self, plan: NegotiatedUploadPlan, reader: BoxAsyncRead) -> Result<UploadReceipt, BlobError>;
}

/// 对齐私有化收费方案：宽限期告警与到期只读软降级（永不锁死客户数据）
pub enum EntitlementStatus {
    Active { plan: String, seat_limit: Option<u32> },
    GracePeriod { expires_in_secs: u64, notice: String },
    ExpiredReadOnly { reason: String },
}

pub enum VerifiedPrincipal {
    /// 来自本机 0600 鉴权 Socket 的宿主调用者
    LocalHost { caller_pid: Option<u32>, account_id: Option<UserId> },
    /// 普通云端工作区通过访问策略校验的成员
    CloudMember { user_id: UserId, access_proof: AccessStamp },
    /// E2EE 工作区经本地已验证账本与设备签名确认的调用者
    EncryptedMember {
        account_id: UserId,
        execution_user_id: UserId,
        device_pubkey: PublicKey,
        machine_generation: MachineGenerationProof,
    },
}

#[async_trait::async_trait]
pub trait WorkspaceSecurityPolicy: Send + Sync {
    fn mode(&self) -> WorkspaceContentMode;
    async fn verify_rpc_envelope(&self, raw: &[u8]) -> Result<(VerifiedPrincipal, Vec<u8>), SecurityError>;
    async fn verify_queued_turn_intent(&self, item: &QueuedTurn) -> Result<VerifiedPrincipal, SecurityError>;
    fn seal_presence(&self, state: &PresencePayload) -> Result<Vec<u8>, SecurityError>;
}

pub enum SessionCommand {
    /// 幂等唤醒：检查已接收的输入队列/指针并推进下一回合
    WakeDispatch { fast_path: Option<AcceptedInputReceipt> },
    /// 活跃回合中插入 Steer 指令，返回三态结果 (Applied / NotApplied / Unknown)
    Steer { input: FrozenTurnInput, reply: oneshot::Sender<SteerOutcome> },
    /// 用户或调用方请求取消当前回合（支持 Inbox v2 pause 语义）
    CancelTurn { cancel_id: Option<CancelId>, pause_inbox: bool, reply: oneshot::Sender<CancelAck> },
    /// 响应挂起的 ACP 工具权限或 AskQuestion 表单
    ResolvePermission { request_id: PermissionReqId, outcome: PermissionOutcome },
    /// 跨会话 Fork 或 Edit-and-Resend 排他栅栏请求
    RunExclusiveSaga { saga: SessionSaga, reply: oneshot::Sender<Result<SagaReceipt, SessionError>> },
    /// 来自 ACP 子进程流的内部事件通知
    AcpEvent { generation: u64, event: AcpNotification },
    /// 内存压力 GC 或工作区撤销触发的优雅驱逐
    Shutdown { reason: EvictReason, done: oneshot::Sender<()> },
}

pub enum SessionPhase {
    Idle {
        warm_agent: Option<AcpAgentHandle>,
        idle_since: Instant,
    },
    Preparing {
        attempt_id: u64,
        cancel: CancellationToken,
        stage: SessionStartStage,
    },
    RunningTurn {
        turn: Box<ActiveTurnContext>, // 独占持有 transient chunks, permission waiters, steer tracker
        agent: AcpAgentHandle,
        turn_cancel: CancellationToken,
    },
    Draining {
        budget_deadline: Instant,
        cleanup_tracker: TaskTracker,
    },
}
